describe('answering a list_sessions frame', () => {
  it('lists the session user own conversations, forwarding limit and before and serialising times as ISO strings', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
