      listFor: (userId: string | number, options?: SessionListOptions) => {
        asked.push({userId, options});
        return [
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 4,
          },
        ];
      },
    } as unknown as SessionStore;
    const handle = createMessageHandler({} as ChatOrchestrator, store);

    await handle(ws, session, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({asked, sent}).toEqual({
      asked: [{userId: 'u1', options: {limit: 10, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
